<?php
namespace Tests\Feature;use Tests\TestCase;use App\Models\User;use App\Features\Post\Models\Post;use Illuminate\Foundation\Testing\RefreshDatabase;
class BlogAccessTest extends TestCase {use RefreshDatabase;public function test_guest_can_view_public_articles():void{$user=User::factory()->create();$post=Post::factory()->for($user)->create(['is_published'=>true,'published_at'=>now()]);$this->get('/')->assertOk()->assertSee($post->title);$this->get('/articles/'.$post->slug)->assertOk()->assertSee($post->title);}public function test_guest_cannot_open_writer_dashboard():void{$this->get('/dashboard/posts')->assertRedirect('/login');}public function test_member_can_open_dashboard_and_create_post():void{$user=User::factory()->create();$this->actingAs($user)->get('/dashboard/posts')->assertOk();$this->actingAs($user)->post('/dashboard/posts',['title'=>'Artikel Tes','category'=>'Teknologi','content'=>'Isi artikel'])->assertRedirect();$this->assertDatabaseHas('posts',['title'=>'Artikel Tes','user_id'=>$user->id]);}public function test_member_cannot_edit_another_users_post():void{$owner=User::factory()->create();$other=User::factory()->create();$post=Post::factory()->for($owner)->create();$this->actingAs($other)->put('/dashboard/posts/'.$post->id,['title'=>'Hack','category'=>'Teknologi','content'=>'No'])->assertForbidden();}public function test_admin_can_open_user_management():void{$admin=User::factory()->admin()->create();$this->actingAs($admin)->get('/admin/users')->assertOk();}public function test_member_cannot_open_admin():void{$member=User::factory()->create();$this->actingAs($member)->get('/admin/users')->assertForbidden();}public function test_registration_creates_member():void{$this->post('/register',['name'=>'Penulis','email'=>'writer@example.test','password'=>'password123','password_confirmation'=>'password123'])->assertRedirect('/dashboard/posts');$this->assertDatabaseHas('users',['email'=>'writer@example.test','role'=>'member']);}public function test_login_page_is_available():void{$this->get('/login')->assertOk()->assertInertia(fn($page)=>$page->component('Auth/Login'));}}
